//! Versioned context-contract compilation for Worldgen P03 F05-F08.
use std::collections::BTreeSet;
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.context-contract-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ContextContractRequest{pub request_id:String,pub source_version:String,pub target_version:String,pub offered_field_order:Vec<String>,pub required_field_order:Vec<String>,pub semantic_loss_budget:u32,pub replay_identity:ContentHash,pub policy_allow:bool,pub protected_closure:bool,pub federation_approved:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ContextContractReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub disposition:String,pub negotiated_version:String,pub field_order:Vec<String>,pub retained_field_order:Vec<String>,pub missing_field_order:Vec<String>,pub omitted_field_order:Vec<String>,pub semantic_loss_order:Vec<String>,pub replay_identity:ContentHash,pub migration_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ContextContractError{#[error("invalid context contract request: {0}")]Invalid(String),#[error("invalid context contract receipt: {0}")]Receipt(String),#[error("context contract artifact failed: {0}")]Artifact(String)}
fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}
impl ContextContractReceipt{pub fn validate(&self)->Result<(),ContextContractError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.negotiated_version.trim().is_empty()||self.field_order.is_empty()||self.effect_receipts.is_empty()||![&self.replay_identity,&self.migration_digest].into_iter().all(digest){return Err(ContextContractError::Receipt("context contract identity, locality, fields, digests, or effects are incomplete".into()));}for v in [&self.field_order,&self.retained_field_order,&self.missing_field_order,&self.omitted_field_order,&self.semantic_loss_order,&self.effect_receipts]{if !ordered(v){return Err(ContextContractError::Receipt("context contract ordering is not canonical".into()));}}let fields=self.field_order.iter().cloned().collect::<BTreeSet<_>>();let states=self.retained_field_order.iter().chain(&self.missing_field_order).chain(&self.omitted_field_order).cloned().collect::<Vec<_>>();if fields.len()!=self.field_order.len()||states.len()!=fields.len()||states.iter().cloned().collect::<BTreeSet<_>>()!=fields{return Err(ContextContractError::Receipt("context contract fields do not partition".into()));}if self.effect_receipts.iter().any(|e|e!="none:context-contract-validation"&&e!="block:unsafe-release"){return Err(ContextContractError::Receipt("context contract effect is outside validation gate".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["research program lead","schema steward","downstream context consumer"],"behavior":format!("compile a version-pinned context contract for {scale}"),"value":"makes migration, semantic loss, and field coverage explicit before context reuse","input_schema":input_schema,"output_schema":"CompiledResearchContext6@1","effects":["none:context-contract-validation","block:unsafe-release"],"permissions":["validate:research-contract"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY})}
pub fn compile(request:&ContextContractRequest,feature_id:&str,version:&str,require_federation:bool)->Result<ContextContractReceipt,ContextContractError>{if request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||request.request_id.trim().is_empty()||request.source_version.trim().is_empty()||request.target_version.trim().is_empty()||request.field_order_empty()||!ordered(&request.offered_field_order)||!ordered(&request.required_field_order)||request.offered_field_order.iter().collect::<BTreeSet<_>>().len()!=request.offered_field_order.len()||request.semantic_loss_budget==0||!digest(&request.replay_identity){return Err(ContextContractError::Invalid("context contract identity, field coverage, budget, replay, locality, or boundary is invalid".into()));}let offered=request.offered_field_order.iter().cloned().collect::<BTreeSet<_>>();let required=request.required_field_order.iter().cloned().collect::<BTreeSet<_>>();let missing=required.difference(&offered).cloned().collect::<BTreeSet<_>>();let mut retained=offered.clone();let mut omitted=BTreeSet::new();let mut loss=BTreeSet::new();let mut disposition="accepted";let negotiated=request.target_version.clone();if request.source_version!=request.target_version{if request.source_version=="0.9.0"&&request.target_version=="1.0.0"{disposition="migrated";loss.insert("legacy-fields".into());}else{disposition="incompatible";retained.clear();loss.insert("version-incompatibility".into());}}if !missing.is_empty(){disposition="unknown";}if loss.len() as u32>request.semantic_loss_budget{return Err(ContextContractError::Invalid("semantic-loss budget exceeded".into()));}if !request.policy_allow||!request.protected_closure||!request.raw_data_local||require_federation&&!request.federation_approved{disposition="blocked";retained.clear();}let mut fields=offered.clone();fields.extend(required.iter().cloned());if disposition=="blocked"||disposition=="incompatible"{for f in &fields{omitted.insert(f.clone());}}let effect=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec!["none:context-contract-validation".into()]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":request.request_id,"disposition":disposition,"negotiated_version":negotiated,"field_order":fields,"retained_field_order":retained,"missing_field_order":missing,"omitted_field_order":omitted,"semantic_loss_order":loss,"replay_identity":request.replay_identity,"effect_receipts":effect,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let migration_digest=ContentHash::of_value(&payload).map_err(|e|ContextContractError::Artifact(e.to_string()))?;let artifact=json!({"artifact_id":format!("context-contract:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":migration_digest,"boundary":PRECLINICAL_BOUNDARY});let receipt=ContextContractReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:request.request_id.clone(),disposition:disposition.into(),negotiated_version:negotiated,field_order:fields.into_iter().collect(),retained_field_order:retained.into_iter().collect(),missing_field_order:missing.into_iter().collect(),omitted_field_order:omitted.into_iter().collect(),semantic_loss_order:loss.into_iter().collect(),replay_identity:request.replay_identity.clone(),migration_digest,effect_receipts:effect,artifact,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};receipt.validate()?;Ok(receipt)}
trait EmptyField{fn field_order_empty(&self)->bool;}impl EmptyField for ContextContractRequest{fn field_order_empty(&self)->bool{self.offered_field_order.is_empty()}}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn r()->ContextContractRequest{ContextContractRequest{request_id:"contract:req".into(),source_version:"1.0".into(),target_version:"1.0".into(),offered_field_order:vec!["fact".into()],required_field_order:vec!["fact".into()],semantic_loss_budget:2,replay_identity:h("r"),policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn accepted(){assert_eq!(compile(&r(),"AFA-worldgen-P03-F05","worldgen-local-context-contract/1.0",false).unwrap().disposition,"accepted")}#[test]fn missing_unknown(){let mut x=r();x.required_field_order.push("missing".into());x.required_field_order.sort();assert_eq!(compile(&x,"AFA-worldgen-P03-F05","worldgen-local-context-contract/1.0",false).unwrap().disposition,"unknown")}#[test]fn federation_blocked(){let mut x=r();x.federation_approved=false;assert_eq!(compile(&x,"AFA-worldgen-P03-F08","worldgen-federated-continual-context-contract/1.0",true).unwrap().disposition,"blocked")}}
